package com.primehr.security;import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class PerformanceCalibrationPermissionGuardTest{@Test void requiresExactActionAndAgencyWideScope(){AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);PerformanceCalibrationPermissionGuard guard=new PerformanceCalibrationPermissionGuard(client);when(client.resolve(PerformanceCalibrationPermissionGuard.FEATURE,"t")).thenReturn(new EffectiveFeaturePermission("x",false,true,true,true,false,false,true,true,false,false,false,PermissionDataScope.AGENCY_WIDE));assertThatCode(()->guard.require(PrimeHrAction.APPROVE,"t")).doesNotThrowAnyException();assertThatThrownBy(()->guard.require(PrimeHrAction.FINALIZE,"t")).isInstanceOf(AccessDeniedException.class);when(client.resolve(PerformanceCalibrationPermissionGuard.FEATURE,"t")).thenReturn(new EffectiveFeaturePermission("x",false,true,true,true,false,false,true,true,false,false,true,PermissionDataScope.ASSIGNED_RECORDS));assertThatThrownBy(()->guard.require(PrimeHrAction.FINALIZE,"t")).isInstanceOf(AccessDeniedException.class);}}
